noOutput();
setDrawMode('interact');
setTitle('Mask Surface')

// State storage
const rects = [];
let currentRect = null;

// Handle pointer events for drawing and relaying
onPointer((p) => {
  // Relay events to the outlet as per previous behavior
  send(p, { to: 0 });

  const { x, y, type } = p;
  const px = x * width;
  const py = y * height;

  if (type === 'down') {
    // Start a new rectangle
    currentRect = { x: px, y: py, w: 0, h: 0 };
  } else if (type === 'move' && currentRect) {
    // Update size during drag
    currentRect.w = px - currentRect.x;
    currentRect.h = py - currentRect.y;
  } else if (type === 'up' && currentRect) {
    // Finalize rectangle and add to list
    rects.push(currentRect);
    currentRect = null;
  }
});

// Handle incoming messages to clear canvas
onMessage((msg) => {
  if (msg && msg.type === 'clear') {
    rects.length = 0;
    redraw(); // Manually trigger redraw since message isn't a pointer event
  }
});

// Render loop (triggered on interaction or redraw())
function draw() {
  ctx.clearRect(0, 0, width, height);

  ctx.lineWidth = 2;

  // Draw all existing rectangles
  ctx.strokeStyle = '#00ccff';

  for (const r of rects) {
    ctx.strokeRect(r.x, r.y, r.w, r.h);
  }

  // Draw the rectangle currently being dragged
  if (currentRect) {
    ctx.strokeStyle = '#ffffff';
    ctx.setLineDash([4, 4]);
    ctx.strokeRect(currentRect.x, currentRect.y, currentRect.w, currentRect.h);
    ctx.setLineDash([]);
  }
}

setTitle("Multi-Rect Mask");
setPortCount(1, 2);

let rects = [];
const MAX_RECTS = 20;
let isDragging = false;

// Add a 'Clear' setting to the gear menu
settings.define([
  { 
    key: 'clear', 
    label: 'Clear All Rects', 
    type: 'boolean', 
    default: false 
  }
]);

// Handle clearing via settings
settings.onChange((key, value) => {
  if (key === 'clear' && value === true) {
    rects = [];
    updateOutputs();
    // Reset toggle state
    setTimeout(() => settings.set('clear', false), 100);
  }
});

function updateOutputs() {
  // Create a nested array (vec4[]) of exactly MAX_RECTS elements
  // Each element is an array [startX, startY, endX, endY]
  const output = Array.from({ length: MAX_RECTS }, (_, i) => {
    const r = rects[i];
    if (r) {
      return [r.start[0], r.start[1], r.end[0], r.end[1]];
    }
    return [0, 0, 0, 0];
  });

  // Send the nested array to outlet 0
  send(output, {to: 0});
  // Send the current count to outlet 1
  send(rects.length, {to: 1});
}

recv((p) => {
  // In Patchies surface, Y=0 is top. In GLSL UV, Y=0 is bottom.
  const currentY = 1.0 - p.y;

  if (p.type === 'down') {
    if (rects.length < MAX_RECTS) {
      rects.push({
        start: [p.x, currentY],
        end: [p.x, currentY]
      });
      isDragging = true;
    }
  } else if (p.type === 'move' && isDragging) {
    const lastRect = rects[rects.length - 1];
    if (lastRect) {
      lastRect.end = [p.x, currentY];
    }
  } else if (p.type === 'up') {
    if (isDragging) {
      const lastRect = rects[rects.length - 1];
      if (lastRect) {
        lastRect.end = [p.x, currentY];
      }
      isDragging = false;
    }
  } else if (p.type === 'clear') {
    rects = [];
  }

  updateOutputs();
});

// @title Raymarched Morphing
// @param smoothness 0.5 0.0 2.0 "Blending smoothness"
// @param scale 1.0 0.1 2.0 "Shape size"
// @param speed 1.0 0.0 5.0 "Animation speed"
// @param MAX_STEPS 100 1 100 "steps"

#include <lygia/sdf/sphereSDF.glsl>
#include <lygia/sdf/boxSDF.glsl>
#include <lygia/space/rotate.glsl>

uniform float smoothness;
uniform float scale;
uniform float speed;
uniform int MAX_STEPS;

// Maximum raymarching steps and distance
#define MAX_DIST 100.0
#define SURF_DIST 0.001

/**
 * Polynomial smooth minimum (smin) implementation
 * Replacing missing lygia/math/smin.glsl
 */
float smin(float a, float b, float k) {
    float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
    return mix(b, a, h) - k * h * (1.0 - h);
}

// Scene composition using SDFs
float map(vec3 p) {
    float time = iTime * speed;

    // Rotate the coordinate space for the box using Lygia's rotate
    vec3 pBox = rotate(p, time, vec3(0.0, 1.0, 0.5));

    // Create a sphere that moves side to side
    vec3 pSphere = p + vec3(sin(time) * 1.5, 0.0, 0.0);

    float d1 = boxSDF(pBox, vec3(scale));
    float d2 = sphereSDF(pSphere, scale * 1.2);

    // Use the local smin implementation
    return smin(d1, d2, max(smoothness, 0.001));
}

vec3 getNormal(vec3 p) {
    float d = map(p);
    vec2 e = vec2(0.01, 0.0);
    vec3 n = d - vec3(
        map(p - e.xyy),
        map(p - e.yxy),
        map(p - e.yyx)
    );
    return normalize(n);
}

// Raymarching loop
float rayMarch(vec3 ro, vec3 rd) {
    float dO = 0.0;

    for (int i = 0; i < MAX_STEPS; i++) {
        vec3 p = ro + rd * dO;
        float dS = map(p);

        dO += dS;

        if (dO > MAX_DIST || dS < SURF_DIST) break;
    }

    return dO;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    // Camera setup - Zoomed out
    vec3 ro = vec3(0.0, 0.0, -10.0);

    // Mouse interaction for camera rotation
    if (iMouse.z > 0.0) {
        float angleX = (iMouse.y / iResolution.y - 0.5) * 3.14159;
        float angleY = (iMouse.x / iResolution.x - 0.5) * 6.28318;
        ro = rotate(ro, angleX, vec3(1.0, 0.0, 0.0));
        ro = rotate(ro, angleY, vec3(0.0, 1.0, 0.0));
    }

    // Derive camera vectors
    vec3 forward = normalize(-ro);
    vec3 right = normalize(cross(vec3(0.0, 1.0, 0.0), forward));
    vec3 up = cross(forward, right);
    vec3 rd = normalize(uv.x * right + uv.y * up + 1.5 * forward);

    float d = rayMarch(ro, rd);
    vec3 color = vec3(0.0);
    float alpha = 0.0;

    if(d < MAX_DIST) {
        vec3 p = ro + rd * d;
        vec3 n = getNormal(p);

        // Simple Diffuse Lighting
        vec3 lightPos = vec3(2.0, 5.0, -3.0);
        vec3 l = normalize(lightPos - p);
        float dif = clamp(dot(n, l), 0.0, 1.0);

        // Ambient occlusion approximation
        float amb = 0.5 + 0.5 * n.y;

        // Color based on normals and lighting
        color = vec3(dif * amb) + n * 0.1 + 0.2;

        // Tint based on position
        color *= 0.5 + 0.5 * cos(iTime + p.xyx + vec3(0.0, 2.0, 4.0));

        // Gamma correction for object only
        color = pow(color, vec3(0.4545));

        alpha = 1.0;
    } else {
        // Transparent background
        color = vec3(0.0);
        alpha = 0.0;
    }

    fragColor = vec4(color, alpha);
}

// @title Multi-Rect Invert Mask
uniform sampler2D iChannel0;
uniform vec4 iRects[20];
uniform int iCount;

#define RECT_COUNT 20

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    vec4 tex = texture(iChannel0, uv);

    bool isInside = false;

    // Clamp iCount to valid array range
    int activeCount = clamp(iCount, 0, RECT_COUNT);

    for (int i = 0; i < RECT_COUNT; i++) {
        if (i >= activeCount) break;

        vec4 rect = iRects[i];

        // Calculate bounds of the current rectangle
        float xMin = min(rect.x, rect.z);
        float xMax = max(rect.x, rect.z);
        float yMin = min(rect.y, rect.w);
        float yMax = max(rect.y, rect.w);

        // Check if current pixel is inside this rectangle
        if (uv.x >= xMin && uv.x <= xMax && uv.y >= yMin && uv.y <= yMax) {
            isInside = true;
            break; // We found an intersection, no need to check other rects
        }
    }

    // If inside any rectangle, invert the color. Otherwise, show original texture.
    if (isInside) {
        fragColor = vec4(1.0 - tex.rgb, tex.a);
    } else {
        fragColor = tex;
    }
}
